//! stanc3's syntax error messages, by replaying the tokens through stanc3's own LR automaton.
//!
//! stanc3 parses with a Menhir LR(1) automaton and picks each syntax error message by the
//! automaton state in which the error is detected (`parser.messages`). The recursive descent
//! parser of stanc-rs has no such states, so after it rejects a program the tokens are run
//! through a copy of stanc3's automaton, generated by `tools/menhir_tables.py`, to find the
//! state and with it stanc3's message.

use crate::format::Formatter;
use crate::lexer::{Tok, Token};

mod tables {
    include!("lr_tables.rs");
}
use tables::*;

/// Menhir's terminal for a token.
fn terminal(t: &Tok) -> u8 {
    use Tok::*;
    let name = match t {
        Functions => "FUNCTIONBLOCK",
        Data => "DATABLOCK",
        TransformedData => "TRANSFORMEDDATABLOCK",
        Parameters => "PARAMETERSBLOCK",
        TransformedParameters => "TRANSFORMEDPARAMETERSBLOCK",
        Model => "MODELBLOCK",
        GeneratedQuantities => "GENERATEDQUANTITIESBLOCK",
        LBrace => "LBRACE",
        RBrace => "RBRACE",
        LParen => "LPAREN",
        RParen => "RPAREN",
        LBrack => "LBRACK",
        RBrack => "RBRACK",
        LAngle => "LABRACK",
        RAngle => "RABRACK",
        Comma => "COMMA",
        Semi => "SEMICOLON",
        Bar => "BAR",
        Return => "RETURN",
        If => "IF",
        Else => "ELSE",
        While => "WHILE",
        Profile => "PROFILE",
        For => "FOR",
        In => "IN",
        Break => "BREAK",
        Continue => "CONTINUE",
        Void => "VOID",
        Int => "INT",
        Real => "REAL",
        Complex => "COMPLEX",
        Vector => "VECTOR",
        RowVector => "ROWVECTOR",
        ComplexVector => "COMPLEXVECTOR",
        ComplexRowVector => "COMPLEXROWVECTOR",
        Tuple => "TUPLE",
        Array => "ARRAY",
        Matrix => "MATRIX",
        ComplexMatrix => "COMPLEXMATRIX",
        Ordered => "ORDERED",
        PositiveOrdered => "POSITIVEORDERED",
        Simplex => "SIMPLEX",
        UnitVector => "UNITVECTOR",
        SumToZeroVector => "SUMTOZEROVEC",
        SumToZeroMatrix => "SUMTOZEROMAT",
        CholeskyFactorCorr => "CHOLESKYFACTORCORR",
        CholeskyFactorCov => "CHOLESKYFACTORCOV",
        CorrMatrix => "CORRMATRIX",
        CovMatrix => "COVMATRIX",
        ColumnStochasticMatrix => "STOCHASTICCOLUMNMATRIX",
        RowStochasticMatrix => "STOCHASTICROWMATRIX",
        Lower => "LOWER",
        Upper => "UPPER",
        Offset => "OFFSET",
        Multiplier => "MULTIPLIER",
        Jacobian => "JACOBIAN",
        QMark => "QMARK",
        Colon => "COLON",
        Bang => "BANG",
        Minus => "MINUS",
        Plus => "PLUS",
        Hat => "HAT",
        EltPow => "ELTPOW",
        Transpose => "TRANSPOSE",
        Times => "TIMES",
        Divide => "DIVIDE",
        Modulo => "MODULO",
        IDivide => "IDIVIDE",
        LDivide => "LDIVIDE",
        EltTimes => "ELTTIMES",
        EltDivide => "ELTDIVIDE",
        Or => "OR",
        And => "AND",
        Equals => "EQUALS",
        NEquals => "NEQUALS",
        Leq => "LEQ",
        Geq => "GEQ",
        Tilde => "TILDE",
        Assign => "ASSIGN",
        PlusAssign => "PLUSASSIGN",
        MinusAssign => "MINUSASSIGN",
        TimesAssign => "TIMESASSIGN",
        DivideAssign => "DIVIDEASSIGN",
        EltTimesAssign => "ELTTIMESASSIGN",
        EltDivideAssign => "ELTDIVIDEASSIGN",
        Print => "PRINT",
        Reject => "REJECT",
        FatalError => "FATAL_ERROR",
        Truncate => "TRUNCATE",
        Target => "TARGET",
        IntLit(_) => "INTNUMERAL",
        RealLit(_) => "REALNUMERAL",
        DotNumeral(_) => "DOTNUMERAL",
        ImagLit(_) => "IMAGNUMERAL",
        StringLit(_) => "STRINGLITERAL",
        Ident(_) => "IDENTIFIER",
        Eof => "EOF",
    };
    TERMINALS
        .iter()
        .position(|n| *n == name)
        .expect("known terminal") as u8
}

/// The action of `state` on terminal `t`: `Some(s >= 0)` shifts to state `s`, `Some(-p - 1)`
/// reduces production `p`.
fn action(state: usize, t: u8) -> Option<i32> {
    let (lo, hi) = (
        ACTION_START[state] as usize,
        ACTION_START[state + 1] as usize,
    );
    ACTIONS[lo..hi]
        .binary_search_by_key(&t, |a| a.0)
        .ok()
        .map(|i| ACTIONS[lo + i].1)
}

fn goto(state: usize, nt: u16) -> usize {
    let (lo, hi) = (GOTO_START[state] as usize, GOTO_START[state + 1] as usize);
    let i = GOTOS[lo..hi]
        .binary_search_by_key(&nt, |g| g.0)
        .expect("goto exists");
    GOTOS[lo + i].1 as usize
}

/// Where the automaton rejects `tokens`: the index of the token stanc3 reports the error at, and
/// the state. Like stanc3, when the state that read the offending token could have shifted the
/// `UNREACHABLE` token, the error is reported at the token before.
fn error_state(tokens: &[Token], functions_only: bool) -> Option<(usize, usize)> {
    let unreachable = TERMINALS
        .iter()
        .position(|n| *n == "UNREACHABLE")
        .expect("UNREACHABLE") as u8;
    let mut stack = vec![if functions_only {
        START_FUNCTIONS_ONLY
    } else {
        START_PROGRAM
    } as usize];
    let mut i = 0;
    // The state in which token `i` was first needed.
    let mut input_state = None;
    loop {
        let s = *stack.last().expect("nonempty");
        let act = if DEFAULT_REDUCTION[s] >= 0 {
            -DEFAULT_REDUCTION[s] - 1
        } else {
            let t = terminal(&tokens.get(i)?.tok);
            let first = *input_state.get_or_insert(s);
            match action(s, t) {
                Some(a) => a,
                None => {
                    let at = if i > 0 && action(first, unreachable).is_some() {
                        i - 1
                    } else {
                        i
                    };
                    return Some((at, s));
                }
            }
        };
        if act >= 0 {
            stack.push(act as usize);
            i += 1;
            input_state = None;
            continue;
        }
        let p = (-act - 1) as usize;
        if PROD_LHS[p] == u16::MAX {
            // The start production: the input is accepted.
            return None;
        }
        stack.truncate(stack.len() - PROD_LEN[p] as usize);
        let top = *stack.last().expect("nonempty");
        stack.push(goto(top, PROD_LHS[p]));
    }
}

/// The state's message text, laid out as stanc3 prints it.
fn render(msg: &str) -> String {
    // Styles are zero width; stanc3's build turns `\n` into `@.`.
    let mut plain = String::new();
    let mut rest = msg;
    while let Some(k) = rest.find("@{<") {
        plain.push_str(&rest[..k]);
        rest = &rest[k + 3..];
        rest = &rest[rest.find('>').map_or(0, |j| j + 1)..];
    }
    plain.push_str(rest);
    let plain = plain.replace("@}", "").replace('\n', "@.");
    let mut f = Formatter::new();
    f.pf(&plain);
    f.finish().trim_end().to_string()
}

/// stanc3's message for the syntax error in `tokens`, with the index of the token it is found
/// at; `None` when stanc3's automaton accepts the tokens.
pub fn syntax_error_message(tokens: &[Token], functions_only: bool) -> Option<(usize, String)> {
    let (i, state) = error_state(tokens, functions_only)?;
    let m = MESSAGE_OF_STATE[state];
    (m != u16::MAX).then(|| (i, render(MESSAGES[m as usize])))
}
